#include <core.p4>
#include <v1model.p4>

// Define the MAC address type
typedef bit<48> macAddr_t;

// Define the Ethernet header
header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16> etherType;
}

// Define the IP header
header ipv4_t {
    bit<4> version;
    bit<4> ihl;
    bit<8> diffserv;
    bit<16> totalLen;
    bit<16> identification;
    bit<3> flags;
    bit<13> fragOffset;
    bit<8> ttl;
    bit<8> protocol;
    bit<16> hdrChecksum;
    ipaddr_t srcAddr;
    ipaddr_t dstAddr;
}

// Define the ACL entry
struct aclEntry_t {
    ipaddr_t ipDst;
    bit<8> newTtl;
}

// Define the headers structure
struct headers {
    ethernet_t eth;
    ipv4_t ip;
    aclEntry_t acl;
}

// Define the metadata
struct metadata {
}

// Parser definition
parser MyParser(packet_in packet, out headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    state start {
        packet.extract(hdr.eth);
        transition select(hdr.eth.etherType) {
            0x0800: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ip);
        transition select(hdr.ip.protocol) {
            1: process_acl; // ICMP
            default: accept;
        }
    }

    state process_acl {
        packet.extract(hdr.acl);
        apply {
            hdr.ip.ttl = hdr.ip.ttl - hdr.acl.newTtl;
            hdr.ip.hdrChecksum = 0; // Clear current checksum
            hdr.ip.hdrChecksum = computeIpChecksum(hdr.ip); // Recalculate checksum
        }
        transition accept;
    }
}

// Checksum computation function
function bit<16> computeIpChecksum(ipv4_t ip) {
    bit<16> sum = 0;
    sum += ip.version << 12 | ip.ihl << 8 | ip.diffserv;
    sum += ip.totalLen;
    sum += ip.identification;
    sum += ip.flags << 13 | ip.fragOffset;
    sum += ip.ttl << 8 | ip.protocol;
    sum += ip.hdrChecksum;
    sum += ip.srcAddr[31:16] | ip.srcAddr[15:0];
    sum += ip.dstAddr[31:16] | ip.dstAddr[15:0];

    while (sum >> 16 != 0) {
        sum = (sum & 0xffff) + (sum >> 16);
    }

    return ~sum & 0xffff;
}

// Control plane functions
control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}

control MyIngress(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    apply { }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t standard_metadata) {
    apply { }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {
        hdr.ip.hdrChecksum = computeIpChecksum(hdr.ip);
    }
}

// Deparser definition
control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.eth);
        packet.emit(hdr.ip);
    }
}

// Main switch instantiation
V1Switch(
    MyParser(),
    MyVerifyChecksum(),
    MyIngress(),
    MyEgress(),
    MyComputeChecksum(),
    MyDeparser()
) main;

