function hash_fn(bit<32> secret0, bit<32> secret1, bit<32> v0, bit<32> v1, bit<32> v2, bit<32> v3) : bit<32> {
    return siphash(secret0, secret1, v0, v1, v2, v3);
}

control MyIngress(inout headers_t hdr,
                  inout metadata_t meta,
                  inout standard_metadata_t standard_metadata){

    const bit<32> SECRET0 = 0x12345678;
    const bit<32> SECRET1 = 0x87654321;

    action validate_syn_cookie() {
        bit<32> computed_cookie = hash_fn(SECRET0, SECRET1, hdr.ipv4.srcAddr, hdr.ipv4.dstAddr, hdr.tcp.srcPort, hdr.tcp.dstPort);
        if (computed_cookie != hdr.tcp.seqNum) {
            meta.punt_reason = PuntReason_t.FLOW_UNKNOWN;
            meta.opcode = ControllerOpcode_t.NO_OP;
            standard_metadata.egress_spec = CPU_PORT;
            mark_to_drop(standard_metadata);
        } else {
            // Proceed with normal processing
        }
    }

    apply {
        if (hdr.tcp.isValid() && hdr.tcp.flags[2]) { // Check if it's a SYN packet
            validate_syn_cookie();
        } else if (hdr.ipv4.isValid()) {
            // Normal processing for other packets
        } else {
            // Drop invalid packets
            mark_to_drop(standard_metadata);
        }
    }
}

