    bit<16> urgentPtr;
}

struct metadata {
    macAddr_t learnedDstMac[256]; // Array to store up to 256 learned MAC addresses
    bool initialized[256];         // Array to track initialization status
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t        tcp;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol){
            TYPE_TCP: tcp;
            default: accept;
        }
    }

    state tcp {
       packet.extract(hdr.tcp);
       transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    table learn_mac {
        key = { hdr.ipv4.srcAddr : lpm; }
        actions = {
            ModifyMAC(hdr.ethernet.dstAddr);
        }
        size = 1024;
        default_action = NoAction;
    }

    table filter_tcp {
        key = { hdr.ipv4.dstAddr : lpm; }
        actions = {
            ModifyTCP(hdr.tcp.seqNo, hdr.tcp.ackNo);
            Drop();
        }
        size = 1024;
        default_action = Drop();
    }

    action ModifyMAC(macAddr_t newDstAddr) {
        meta.learnedDstMac[standard_metadata.ingress_port] = newDstAddr;
        meta.initialized[standard_metadata.ingress_port] = true;
    }

    action ModifyTCP(bit<32> newSeqNo, bit<32> newAckNo) {
        hdr.tcp.seqNo = newSeqNo;
        hdr.tcp.ackNo = newAckNo;
    }

    action Drop() {
        mark_to_drop(standard_metadata);
    }

    apply {
        if (hdr.ipv4.isValid()) {
            if (!meta.initialized[standard_metadata.ingress_port]) {
                learn_mac.apply();
            } else {
                if (hdr.tcp.isValid()) {
                    filter_tcp.apply();
                }
            }
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {  }
}

control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

