    bit<1>  psh;
    bit<1>  rst;
    bit<1>  syn;
    bit<1>  fin;
    bit<16> window;
    bit<16> checksum;
    bit<16> urgentPtr;
}

struct metadata {
    bit<32> fingerprint;
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    tcp_t        tcp;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            TYPE_TCP: parse_tcp;
            default: accept;
        }
    }

    state parse_tcp {
        packet.extract(hdr.tcp);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    table sample_traffic {
        key = { standard_metadata.ingress_port : exact; }
        actions = { Sample; Accept; }
        size = 1024;
        default_action = Accept();
    }

    table fingerprint_table {
        key = { hdr.tcp.srcPort : exact; hdr.tcp.dstPort : exact; }
        actions = { Fingerprint; Accept; }
        size = FINGERPRINT_TABLE_SIZE;
        default_action = Accept();
    }

    action Sample() {
        if (uniform(0, 1) < SAMPLE_RATE) {
            meta.fingerprint = hash(hdr.tcp.payload, HashAlgorithm.xxhash32);
        }
    }

    action Fingerprint() {
        meta.fingerprint = hash(hdr.tcp.payload, HashAlgorithm.xxhash32);
    }

    apply {
        sample_traffic.apply();
        if (hdr.ipv4.isValid() && hdr.tcp.isValid()) {
            fingerprint_table.apply();
        }
    }
}

