            TYPE_IPV4: parse_ipv4;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            1: forward_packet; // ICMP
            6: forward_packet; // TCP
            17: forward_packet; // UDP
            default: filter_packet;
        }
    }

    state forward_packet {
        transition accept;
    }

    state filter_packet {
        if (!((hdr.ipv4.srcAddr == 0xC0A80101 /* 192.168.1.1 */) || (hdr.ipv4.srcAddr == 0xC0A80102 /* 192.168.1.2 */))) {
            transition accept;
        } else {
            transition reject;
        }
    }

    state reject {
        transition accept;
    }
}

